
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_revb3lyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_revb3lyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.511513159916524e+00, -3.445582560891006e+00, -3.353240509335975e+00, -3.225412148749346e+00, -3.051411926030605e+00, -2.820202049869008e+00, -2.523345490151419e+00, -2.160232727064421e+00, -1.744720994306489e+00, -1.307296954463963e+00, -8.826292812149752e-01, -6.026044808932581e-01, -5.210255210990234e-01, -4.338499952750101e-01, -3.155914248109711e-01, -1.983834114149097e-01, -1.151784399216704e-01, -7.151237087263236e-02, -4.288221542216014e-02, -2.826888744044369e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


